<div class="page-header"><div><p class="eyebrow">LECTURER GRADEBOOK</p><h1>Score entry</h1><p>Only assigned lecturers can enter or correct scores.</p></div><a href="/grades" class="btn btn-outline-secondary">Back to gradebook</a></div>
<section class="panel mb-4"><div class="panel-heading"><h2>Assessment limits</h2><span class="status-pill <?= $status===false?'draft':e($status) ?>"><?= e($status===false?'draft':$status) ?></span></div><div class="score-limits"><span>CA maximum <strong><?= e($components['ca']['max_score']) ?></strong></span><span>Exam maximum <strong><?= e($components['exam']['max_score']) ?></strong></span><span>Combined maximum <strong>100</strong></span></div></section>
<section class="panel"><div class="panel-heading"><h2>Registered students</h2><span class="subtle-tag">10 rows per page</span></div><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Matric no.</th><th>Student</th><th>CA / Exam</th><th>Computed grade</th><th>Action</th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?= e($r['matriculation_number']) ?></td><td><?= e($r['full_name']) ?></td><td><form id="score-<?= (int)$r['registration_id'] ?>" method="post" action="/grades/save" class="inline-actions"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$course ?>"><input type="hidden" name="semester_id" value="<?= (int)$semester ?>"><input type="hidden" name="registration_id" value="<?= (int)$r['registration_id'] ?>"><input class="form-control form-control-sm score-input" type="number" min="0" step="0.01" max="<?= e($components['ca']['max_score']) ?>" name="ca_score" value="<?= e($r['ca_score']??'') ?>" aria-label="Continuous assessment" required><input class="form-control form-control-sm score-input" type="number" min="0" step="0.01" max="<?= e($components['exam']['max_score']) ?>" name="exam_score" value="<?= e($r['exam_score']??'') ?>" aria-label="Examination score" required></form></td><td><?= e($r['grade']??'Not graded') ?></td><td><button class="btn btn-outline-primary btn-sm" type="submit" form="score-<?= (int)$r['registration_id'] ?>" <?= $status!==false && $status!=='rejected'?'disabled':'' ?>>Save</button></td></tr><?php endforeach; ?></tbody></table><?php if(!$items):?><p class="empty-state">No registered students in this course.</p><?php endif; ?></div><?= page_links($page,$total,'/grades/entry?course_id='.$course.'&semester_id='.$semester) ?>
<form method="post" action="/grades/submit" class="mt-4"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$course ?>"><input type="hidden" name="semester_id" value="<?= (int)$semester ?>"><button class="btn btn-primary" <?= $status!==false && $status!=='rejected'?'disabled':'' ?>>Submit completed roster for review</button></form></section>
